"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4078],{99042:e=>{e.exports=JSON.parse('{"functions":[{"name":"GetShield","desc":"Returns `(currentShield, maxShield)`.","params":[],"returns":[{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":97,"path":"src/ServerStorage/SharedModules/TrainShieldManager.luau"}},{"name":"SetJumpFreeze","desc":"Suspends shield damage for the duration of a jump. The shield has no\\ncontinuous drain, so unlike the fuel freeze there is nothing to re-snapshot.","params":[{"name":"frozen","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":106,"path":"src/ServerStorage/SharedModules/TrainShieldManager.luau"}},{"name":"ApplyDamage","desc":"The single damage sink \u2014 future enemy AI / hazards call this. While the\\nshield holds, it absorbs the hit and clamps at 0; the hit that empties the\\nshield discards its excess (no fuel damage that hit). Once the shield is\\nalready at 0, further hits convert to fuel damage via\\n`TrainConfig.FUEL_DAMAGE_FACTOR` and route to `TrainFuelManager.ApplyFuelDamage`,\\nwhich may end the round. No-op before the round is live or after game over.","params":[{"name":"amount","desc":"","lua_type":"number"},{"name":"source","desc":"","lua_type":"any?"}],"returns":[],"function_type":"static","source":{"line":119,"path":"src/ServerStorage/SharedModules/TrainShieldManager.luau"}},{"name":"Initialize","desc":"Initialises shield state and wires the recharge packet, join sync, buff\\nsubscriptions, and pre-game freeze. Call exactly once from the owning server\\nscript.","params":[],"returns":[],"function_type":"static","source":{"line":242,"path":"src/ServerStorage/SharedModules/TrainShieldManager.luau"}}],"properties":[],"types":[],"name":"TrainShieldManager","desc":"Global, server-authoritative module that manages the train\'s shield pool \u2014 a\\nscalar in `0 .. maxShield`, where `maxShield` is derived from a base capacity\\nplus the Tech Tree\'s additive `MaxHP` buff, scaled by the party `TrainShield`\\nperk. The shield is the entity enemy AI / hazards will damage (future combat)\\nvia `ApplyDamage`, and players restore it by feeding Energy tools at a tagged\\nconsole (`RechargeFromEnergy`). Reaching 0 no longer ends the round by itself \u2014\\nonce the shield is down, further hits bleed into fuel via\\n`TrainFuelManager.ApplyFuelDamage`.","realm":["Server"],"source":{"line":52,"path":"src/ServerStorage/SharedModules/TrainShieldManager.luau"}}')}}]);